package com.bank.qa.coding;

import java.util.*;

class DedupeTasks {

    // Remove duplicates from an array, PRESERVING order.
    // Time: O(n). Space: O(n). Edge: empty / all-dupes / nulls.
    List<String> dedupeArray(String[] arr) {
        if (arr == null) return List.of();
        Set<String> seen = new HashSet<>();
        List<String> out = new ArrayList<>();
        for (String x : arr) if (seen.add(x)) out.add(x); // add() false if already present
        return out;
    }

    // Follow-up: dedupe OBJECTS by a specific property (accountNo), keep first.
    // Time: O(n). Space: O(n). Edge: empty / null key.
    List<Customer> dedupeByAccount(List<Customer> customers) {
        Set<String> seenKeys = new HashSet<>();
        List<Customer> out = new ArrayList<>();
        for (Customer c : customers)
            if (c != null && seenKeys.add(c.accountNo)) out.add(c); // key, not reference
        return out;
    }
}
