package com.bank.qa.coding;

import java.util.*;
import java.util.logging.*;

public class SdetCodingDemo {
    private static final Logger log = Logger.getLogger(SdetCodingDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new CodingLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        StringTasks st = new StringTasks();
        DedupeTasks dt = new DedupeTasks();

        log.info("=== First non-repeating character (O(n), count map) ===");
        log.info("'TXNAABTC' -> " + st.firstNonRepeating("TXNAABTC")); // X
        log.info("'' -> " + st.firstNonRepeating(""));                 // null (edge)
        log.info("'aabb' -> " + st.firstNonRepeating("aabb"));         // null (all repeat)

        log.info("=== Reverse string without built-ins (O(n), two-pointer) ===");
        log.info("'SAV2001' -> " + st.reverse("SAV2001"));             // 1002VAS
        log.info("'' -> '" + st.reverse("") + "'");                    // '' (edge)

        log.info("=== Remove duplicates from array (O(n), set, order kept) ===");
        log.info(dt.dedupeArray(new String[]{"T1","T2","T1","T3","T2"}).toString()); // [T1,T2,T3]

        log.info("=== Dedupe objects by accountNo (O(n), seen-key set) ===");
        List<Customer> custs = List.of(
            new Customer("SAV2001","Rajesh"), new Customer("CUR3001","Priya"),
            new Customer("SAV2001","Rajesh K"));  // same account, different object
        log.info(dt.dedupeByAccount(custs).toString()); // [SAV2001:Rajesh, CUR3001:Priya]

        log.info("=== Second-highest salary -> see SQL (DENSE_RANK vs subquery) ===");
        log.info("DENSE_RANK handles ties (second DISTINCT); subquery simple; "
            + "single salary -> NULL/empty.");
    }
}

